const BULAN = ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
const HARI = ['Ahad','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'];
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const tanggalPanjang = (ymd) => {
  const [y, m, d] = ymd.split('-').map(Number);
  const dow = new Date(Date.UTC(y, m - 1, d)).getUTCDay();
  return HARI[dow] + ', ' + d + ' ' + BULAN[m - 1] + ' ' + y;
};

// Batas pesan Telegram 4096 karakter; sisakan ruang untuk judul lanjutan.
const MAKS = 3800;
const config = $('Config').first().json;
const kota = $('Daftar Kota').all().map((i) => i.json);
const responses = $input.all().map((i) => i.json);

// Satu kota gagal (error/timeout) tidak boleh menggagalkan kota lain,
// tapi bila semuanya gagal, workflow harus error agar terlihat di n8n.
const berhasil = responses.filter((r) => Array.isArray(r.data));
if (berhasil.length === 0) {
  throw new Error('Semua request jadwal-majelis gagal: ' + JSON.stringify(responses[0]).slice(0, 300));
}

const pesan = [];
responses.forEach((res, i) => {
  if (!Array.isArray(res.data) || res.data.length === 0) return;
  const namaKota = (kota.find((k) => k.city_code === res.meta?.city_code) ?? kota[i]).nama;

  const judul = '🕌 <b>Jadwal Majelis Hari Ini</b>\n'
    + '📍 <b>' + esc(namaKota) + '</b>\n'
    + '🗓 ' + tanggalPanjang(res.meta.from) + '\n';
  const penutup = '\n<a href="' + esc(config.base_url) + '/jadwal-majelis">Lihat semua jadwal di Syaikhuna</a>';

  const baris = res.data.map((j) => {
    const nama = j.url ? '<a href="' + esc(j.url) + '">' + esc(j.nama_jadwal) + '</a>' : esc(j.nama_jadwal);
    const info = [j.majelis?.nama, j.guru?.nama].filter(Boolean).map(esc).join(' · ');
    const akses = j.access && j.access !== 'Umum' ? ' <i>(' + esc(j.access) + ')</i>' : '';
    const peta = j.majelis?.maps ? '\n   🗺 <a href="' + esc(j.majelis.maps) + '">Peta lokasi</a>' : '';
    return '⏰ <b>' + (j.waktu ? esc(j.waktu) + ' WITA' : 'Waktu menyusul') + '</b>' + akses + '\n   ' + nama
      + (info ? '\n   ' + info : '') + peta;
  });

  let isi = judul + (res.meta.is_ramadhan ? '<i>Jadwal yang libur selama Ramadan tidak ditampilkan.</i>\n' : '') + '\n';
  let bagian = 1;
  for (const b of baris) {
    if ((isi + b + '\n\n' + penutup).length > MAKS) {
      pesan.push(isi.trimEnd());
      bagian++;
      isi = '🕌 <b>' + esc(namaKota) + '</b> (lanjutan ' + bagian + ')\n\n';
    }
    isi += b + '\n\n';
  }
  pesan.push((isi + penutup.trimStart()).trimEnd());
});

return pesan.map((text) => ({ json: { text } }));
